+const localLogoUrls = import.meta.glob<string>(
+  "/node_modules/@pantoken/plugin-logos/dist/*.png",
+  { eager: true, import: "default", query: "?url" },
+);
+
+function buildSelectedAssetUrl(file: CdnFile): string {
+  if (providerSelect.value !== LOCAL_PROVIDER_ID) {
+    return buildFileUrl(file, providerSelect.value);
+  }
+  const localUrl = localLogoUrls[`/node_modules/${file.package}/${file.path}`];
+  if (!localUrl) throw new Error(`Missing local package asset: ${file.package}/${file.path}`);
+  return localUrl;
+}
